('home', 'Home Page', 'High-Protein Recipes: 50 Guilt-Free Healthy Recipes Under 400 Calories', 'Boost your metabolism and burn fat with BHYou. Get 50 mouth-watering, high-protein recipes under 400 calories. Includes desserts and meal plans!', 'high protein recipes', 92, '', 'https://bhyou.com', 'High-Protein Recipes: 50 Guilt-Free Healthy Recipes Under 400 Calories', 'Get 50 protein-packed, low-calorie recipes designed to burn fat and build muscle. Standard and free options available!', 'https://i.ibb.co/8g3JXwpS/HIGH-PROTEIN-RECIPES.jpg'),
('sales', 'Ebook Sales Page', 'High-Protein Recipes Cookbook - Get 50 Recipes for $11.99', 'Get your copy of 50 High-Protein Recipes Under 400 Calories. Fuel your muscles, lose fat, and satisfy sweet cravings. Start cooking healthy today!', 'under 400 calories', 96, 'cookbook', 'https://bhyou.com/cookbook', 'High-Protein Recipes: 50 Guilt-Free Healthy Recipes Under 400 Calories', 'Ready to burn fat without giving up desserts? Purchase our premium cookbook today for only $11.99!', 'https://i.ibb.co/8g3JXwpS/HIGH-PROTEIN-RECIPES.jpg'),
('dessert-sales', 'High-Protein Dessert Cookbook', 'High-Protein Dessert Cookbook | 70 Healthy Recipes Under 400 Calories', 'Discover 70 delicious high-protein dessert recipes under 400 calories, with full macros, easy ingredients, meal prep tips, and beginner-friendly instructions.', 'high-protein dessert cookbook', 98, 'dessert-cookbook', 'https://bhyou.com/dessert-cookbook', 'The High-Protein Dessert Cookbook: 70 Healthy Recipes Under 400 Calories', 'Love desserts but still want to hit your protein goals? 70 delicious high-protein dessert recipes under 400 calories. Instant digital download!', '/dessert_cookbook_cover.png')
